(async () => {
  await once(v, 'canplaythrough');
  v.currentTime = 99;
  await once(v, 'seeked');
  await sleep(100);
  const atEnd = S(v);
  mark(v, 'play()');
  const pr = v.play().then(() => 'resolved', e => e.name);
  await sleep(600);
  const after = S(v);
  v.pause();
  return {atEnd, promise: await pr, after, ev: evs()};
})()

(async () => {
  const m = v;
  await once(m, 'canplaythrough');
  m.play();
  await once(m, 'playing');
  await sleep(600);
  m.remove();
  await sleep(300);
  document.body.appendChild(m);
  await sleep(300);
  const back = S(m);
  mark(m, 'play() after re-insertion');
  const pr = m.play().then(() => 'resolved', e => e.name);
  await sleep(600);
  const after = S(m);
  m.pause();
  return {back, promise: await pr, after, ev: evs()};
})()

