(async () => {
  if (v.readyState < 4) await once(v, 'canplaythrough', 3000);
  await sleep(300);
  const before = S(v);
  let errAt = null;
  v.addEventListener('error', () => { errAt = r2(v.currentTime); });
  mark(v, 'play()');
  const pr = v.play().then(() => 'resolved', e => e.name + ': ' + e.message);
  await Promise.race([once(v, 'error', 4000), once(v, 'ended', 4000)]);
  await sleep(300);
  const after = S(v);
  v.pause();
  return {before, promise: await pr, errAt, after, ev: evs()};
})()

